DROP TABLE IF EXISTS `ranobe_volumes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ranobe_volumes` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `volume_number` decimal(8,2) NOT NULL,
  `general_number` int NOT NULL,
  `cover_image` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `cover_image_mobile` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `release_date_book` datetime NOT NULL,
  `release_date_digital` datetime NOT NULL,
  `ranobe_year_id` bigint unsigned NOT NULL,
  `pages_quantity` int NOT NULL,
  `isbn` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `all_chapters` int DEFAULT NULL,
  `volume_description` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `volume_images` text COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`id`),
  KEY `ranobe_volumes_ranobe_year_id_foreign` (`ranobe_year_id`),
  CONSTRAINT `ranobe_volumes_ranobe_year_id_foreign` FOREIGN KEY (`ranobe_year_id`) REFERENCES `ranobe_years` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

